mapper.select:
SELECT TO_CHAR(T.CHECK_NO) AS CHECK_NO, TO_CHAR(T.BASIC_NO) AS BASIC_NO, T.TEA_EMPID, T.TEA_LOCAL_NAME, GET_GLOBAL_NAME(H.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) AS TEA_POST_GRADE_NAME, GET_DEPT_NAME(H.DEPTNO, #{lang, jdbcType=VARCHAR}) AS TEA_DEPT_NAME, T.STU_EMPID, T.STU_LOCAL_NAME, AS GROOMING, TO_CHAR(T.ALLSCORE) AS ALLSCORE, T.OTHER_ADVISE FROM EDU_TEACHER_CHECK T LEFT JOIN HR_EMPLOYEE H ON H.EMPID = T.TEA_EMPID WHERE T.BASIC_NO = #{basicNo, jdbcType=NUMERIC} AND T.ACTIVITY = 1 AND T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND T.TEA_EMPID = #{teaEmpId, jdbcType=VARCHAR}
ORDER BY T.TEA_EMPID, T.STU_EMPID

mapper.update:
UPDATE EDU_TEACHER_CHECK
   SET GROOMING = #{grooming, jdbcType=NUMERIC},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP = #{adminIP, jdbcType=VARCHAR}
 WHERE BASIC_NO = #{basicNo, jdbcType=NUMERIC}
   AND TEA_EMPID = #{teaEmpId, jdbcType=VARCHAR}
   AND STU_EMPID = #{stuEmpId, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
